def is_match(s, p):
    def match(i, j):
        if j == len(p):
            return i == len(s)
        if p[j] == '*':
            return match(i, j + 1) or (i < len(s) and match(i + 1, j))  # skip the star, or consume one more char
        if i < len(s) and (p[j] == '?' or p[j] == s[i]):
            return match(i + 1, j + 1)
        return False

    return match(0, 0)


